// ---------------------------------------------------------------------------
// 3D Mold Casting Simulator
// ---------------------------------------------------------------------------
//
// Simulates what would be cast from a mold (either a mold body in the scene,
// such as 'Concrete Mold' or 'Simulated: Mold', or a mold generated by
// moldExporter.ts) and returns the 3D cast mesh so it can be inspected,
// measured, or placed in the scene as a cast body.
//
// Primary Path:
//   High-precision 3D CSG via Manifold WebAssembly. An interior probe volume
//   is carved by subtracting the mold half solids, decomposing the resulting
//   voids into disconnected components, and selecting the primary casting cavity
//   (discarding alignment pin-socket clearance gaps and outer pry notches).
//
// A mold whose surface will not close even after welding seams is refused:
// repairing it here changes the mold, and the casting with it.
//
// Fallback Path:
//   Exact ray column spans (castColumnSpans) + dual contouring / surface nets
//   (meshField) if the Manifold CSG itself fails.
// ---------------------------------------------------------------------------

import * as THREE from 'three';
import type { Manifold as ManifoldT, ManifoldToplevel } from 'manifold-3d';
import type { FeedRoute, SceneNode, VentStub } from '../types/scene';
import type { SurfaceTexture } from './surfaceTexture';
import { loadManifold } from './sculptCut';
import { manifoldToMeshMm } from './timberBreakdown';
import { castColumnSpans, type ColumnGrid } from './columnSolid';
import { meshField } from './multiSetupMesh';
import type { IndexedMesh } from './stlMesh';
import { appendSolidTriangles } from './contourSliceExporter';
import { getNodeWorldTransform, getGeomFrame } from './laserCutExporter';
import { resolveCsgGeoms } from './csg';
import { analyzeMesh } from './meshIntegrity';
import type { MoldExportResult, MoldSummary } from './moldExporter';
import { unrotateFromPull } from './moldPullDirection';
import { pourIntoCavity, probeFacesTouched, type PourInfo, type PourOptions } from './pourCast';
import { castMaterial, type CastMaterialId } from './castMaterials';
import { fillCellMm, simulateFill, voxelizeCavity, type FillDomain, type FillResult } from './pourFill';
import { VENT_TAPER_MM } from './moldSprue';
import { cutBores, feedRouteOf, FEED_WALL_MM, ventStubsOf, type BoreCut } from './moldGating';

export interface MoldCastSimulationOptions {
  /** Whether to trim narrow sprue/vent runner stubs sticking up to the outer mold face (default: false — keeps what the mold actually casts, or true when comparing part volume). */
  trimChannels?: boolean;
  /** Whether to flip an inverted open-mold casting right-side up so its flat poured base sits at Z = 0 (default: true). */
  orientUpright?: boolean;
  /** Whether to bake high-density surface textures (geom.textures) into the cast mesh triangles (default: false to keep scene graph meshes lightweight). */
  includeSurfaceTextures?: boolean;
  /**
   * Pour into bodies that may or may not be a mold: from whichever side holds
   * a pour (or the one given), to a fill height, failing when nothing does.
   */
  pour?: PourOptions;
  /** What is poured into a closed mold, for how narrow a passage its air can rise through (default epoxy). */
  castMaterial?: CastMaterialId;
  /** Pour a closed mold with the air in it (pourFill.ts), so what cannot fill is left out (default true). */
  airAware?: boolean;
}

/** What a closed mold's pour left unfilled, air it could not let out. */
export interface CastFillReport {
  /** Share of the cavity, sprue and vents included, that filled. */
  filledShare: number;
  trappedMm3: number;
  pockets: number;
  largestPocketMm3: number;
}

export interface MoldCastSimulationResult {
  success: boolean;
  error?: string;
  warnings: string[];
  /** Cast part mesh in millimetres, Z up, centered in XY and resting on Z = 0. */
  mesh: IndexedMesh;
  /** Volume of the simulated casting in mm³. */
  castVolumeMm3: number;
  /** Dimensions of the simulated casting in mm. */
  sizeMm: { width: number; depth: number; height: number };
  /** Number of disconnected cavity pieces found before keeping the main casting. */
  cavityComponents: number;
  /** Surface textures transferred and inverted from the mold onto the cast part. */
  textures?: SurfaceTexture[];
  /** For a pour: the side it came from, how deep, and what a rigid mold would hold. */
  pour?: PourInfo;
  /** How far the cast strays from the part it was molded from, mm, when asked for. */
  deviation?: { maxMm: number; meanMm: number };
  /** For a closed mold poured with its air in: what did not fill. */
  fill?: CastFillReport;
}

export interface RawMoldTexture {
  texture: SurfaceTexture;
  worldAtMm: [number, number, number];
  worldNormal: [number, number, number];
  worldUp: [number, number, number];
}

export type InternalCastOptions = MoldCastSimulationOptions & {
  isClamshell?: boolean;
  /** What comes off a clamshell's casting along its own bores: a bottom fill's route, the vents' stubs. */
  feedTrim?: BoreCut[];
  flipUpright?: boolean;
  partingZ?: number;
  halves?: (Float64Array | number[])[];
  negativeHalves?: (Float64Array | number[])[];
  rawTextures?: RawMoldTexture[];
  /** The mold body's name, for a refusal. */
  moldName?: string;
};

/**
 * Welds vertices within quantum (default 0.01 mm) and strips degenerate triangles
 * and identical duplicates.
 */
export function weldTriangles(
  soup: ArrayLike<number>,
  quantum = 1e-3,
): { positions: Float32Array; faces: Uint32Array } {
  const index = new Map<string, number>();
  const positions: number[] = [];
  const idOf = (x: number, y: number, z: number) => {
    const key = quantum <= 0
      ? `${x},${y},${z}`
      : `${Math.round(x / quantum)},${Math.round(y / quantum)},${Math.round(z / quantum)}`;
    let id = index.get(key);
    if (id === undefined) {
      id = positions.length / 3;
      positions.push(x, y, z);
      index.set(key, id);
    }
    return id;
  };

  const faces: number[] = [];
  const seenForward = new Set<string>();

  for (let t = 0; t + 8 < soup.length; t += 9) {
    const a = idOf(soup[t], soup[t + 1], soup[t + 2]);
    const b = idOf(soup[t + 3], soup[t + 4], soup[t + 5]);
    const c = idOf(soup[t + 6], soup[t + 7], soup[t + 8]);
    if (a === b || b === c || a === c) continue;

    // Cyclic normalization: min index first
    let v0 = a, v1 = b, v2 = c;
    if (v1 < v0 && v1 < v2) {
      v0 = b; v1 = c; v2 = a;
    } else if (v2 < v0 && v2 < v1) {
      v0 = c; v1 = a; v2 = b;
    }
    const forwardKey = `${v0},${v1},${v2}`;
    if (seenForward.has(forwardKey)) continue;
    seenForward.add(forwardKey);

    faces.push(a, b, c);
  }

  // Compact positions: keep only referenced vertices
  const oldToNew = new Int32Array(positions.length / 3).fill(-1);
  const compactPos: number[] = [];
  const compactFaces = new Uint32Array(faces.length);
  for (let i = 0; i < faces.length; i++) {
    const oldId = faces[i];
    let newId = oldToNew[oldId];
    if (newId === -1) {
      newId = compactPos.length / 3;
      compactPos.push(positions[oldId * 3], positions[oldId * 3 + 1], positions[oldId * 3 + 2]);
      oldToNew[oldId] = newId;
    }
    compactFaces[i] = newId;
  }

  return {
    positions: new Float32Array(compactPos),
    faces: compactFaces,
  };
}

/**
 * Computes the signed enclosed volume of an indexed triangle mesh.
 */
export function computeMeshVolume(positions: Float32Array, faces: Uint32Array): number {
  let vol = 0;
  for (let f = 0; f < faces.length; f += 3) {
    const a = faces[f] * 3, b = faces[f + 1] * 3, c = faces[f + 2] * 3;
    const ax = positions[a], ay = positions[a + 1], az = positions[a + 2];
    const bx = positions[b], by = positions[b + 1], bz = positions[b + 2];
    const cx = positions[c], cy = positions[c + 1], cz = positions[c + 2];
    vol += (ax * (by * cz - bz * cy) + ay * (bz * cx - bx * cz) + az * (bx * cy - by * cx)) / 6;
  }
  return Math.abs(vol);
}

/**
 * Finds the Z height of the primary flat parting face in a mold half.
 * The parting face is a horizontal surface with the largest number of coplanar
 * horizontal triangles among upper Z levels (excluding outer face at Z = 0
 * and small pin tip facets).
 */
function findPartingZ(triangles: { a: [number, number, number]; b: [number, number, number]; c: [number, number, number] }[]): number {
  const zCounts = new Map<number, number>();
  for (const t of triangles) {
    if (Math.abs(t.a[2] - t.b[2]) < 1e-2 && Math.abs(t.b[2] - t.c[2]) < 1e-2 && t.a[2] > 1) {
      const k = Math.round(t.a[2] * 10) / 10;
      zCounts.set(k, (zCounts.get(k) ?? 0) + 1);
    }
  }
  let bestZ = 0;
  let maxCount = 0;
  for (const [z, count] of zCounts.entries()) {
    if (count > maxCount) {
      maxCount = count;
      bestZ = z;
    }
  }
  return bestZ;
}

/**
 * Entry point 1:
 * Simulates casting from a scene node representing a mold body (e.g. 'Concrete Mold').
 */
export async function simulateCastFromMoldNode(
  node: SceneNode,
  options?: MoldCastSimulationOptions,
): Promise<MoldCastSimulationResult> {
  const geomShellsMm: Float64Array[] = [];
  /** The name of the geom each of `geomShellsMm` came from. */
  const geomNames: string[] = [];
  const negativeShellsMm: Float64Array[] = [];
  const allTrisMetres: number[] = [];
  const rawTextures: RawMoldTexture[] = [];
  const warnings: string[] = [];

  const traverse = (n: SceneNode, parentMatrix?: THREE.Matrix4) => {
    // Note: do NOT skip node if node.simulation is set
    const bodyMatrix = getNodeWorldTransform(n, parentMatrix);
    const geoms = resolveCsgGeoms(n, 'render');
    for (const geom of geoms) {
      if (geom.role === 'collision') continue;
      if (geom.textures && geom.textures.length > 0) {
        const frame = getGeomFrame(geom);
        const matrix = new THREE.Matrix4().multiplyMatrices(bodyMatrix, frame.matrix);
        for (const tex of geom.textures) {
          if (!tex.seedAt || tex.seedAt.length < 3) continue;
          const pt = new THREE.Vector3(tex.seedAt[0], tex.seedAt[1], tex.seedAt[2]).applyMatrix4(matrix);
          const sn = tex.seedNormal && tex.seedNormal.length >= 3 ? tex.seedNormal : [0, 1, 0];
          const nLocal = new THREE.Vector3(sn[0], sn[1], sn[2]).normalize();
          // Default planar u tangent (first non-parallel basis axis)
          const uLocal = new THREE.Vector3(1, 0, 0);
          if (Math.abs(nLocal.x) > 0.85) uLocal.set(0, 1, 0);
          uLocal.addScaledVector(nLocal, -uLocal.dot(nLocal)).normalize();
          if (tex.twistDeg) {
            uLocal.applyAxisAngle(nLocal, (tex.twistDeg * Math.PI) / 180);
          }
          const vLocal = new THREE.Vector3().crossVectors(nLocal, uLocal).normalize();
          const wNorm = nLocal.clone().transformDirection(matrix).normalize();
          const wUp = vLocal.clone().transformDirection(matrix).normalize();
          rawTextures.push({
            texture: tex,
            worldAtMm: [pt.x * 1000, pt.y * 1000, pt.z * 1000],
            worldNormal: [wNorm.x, wNorm.y, wNorm.z],
            worldUp: [wUp.x, wUp.y, wUp.z],
          });
        }
      }
      const geomTrisM: number[] = [];
      const srcGeom = options?.includeSurfaceTextures ? geom : { ...geom, textures: undefined };
      appendSolidTriangles(srcGeom, bodyMatrix, geomTrisM);
      if (geomTrisM.length > 0) {
        const geomTrisMm = new Float64Array(geomTrisM.length);
        // Every shell on the same 0.1 µm grid, meshes too. A primitive needs it
        // to weld (its rim vertices come out a few ulps apart), and snapping
        // only primitives left a snapped master and an unsnapped pour box
        // meeting on faces a hair apart, where the union quietly kept the
        // master out: the silicone poured into the space the master filled.
        for (let i = 0; i < geomTrisM.length; i++) {
          const rawMm = geomTrisM[i] * 1000;
          const valMm = Math.round(rawMm * 1e4) / 1e4;
          geomTrisMm[i] = valMm;
          allTrisMetres.push(valMm / 1000);
        }
        geomShellsMm.push(geomTrisMm);
        geomNames.push(geom.name ?? '');
      }
    }

    // If this node has uncompiled negative CSG geoms (e.g. a CSG mold body whose
    // negative mesh geom had a non-manifold edge before repair, or in headless tests),
    // collect those negative geoms so Manifold can subtract them from the mold block.
    const rawGeoms = n.geoms || [];
    const hasCompiledCsgVisual = rawGeoms.some(g => g.csgDerived === 'visual');
    if (!hasCompiledCsgVisual) {
      for (const geom of rawGeoms) {
        if (geom.csgDerived || geom.csg !== 'difference') continue;
        const negTrisM: number[] = [];
        appendSolidTriangles(geom, bodyMatrix, negTrisM);
        if (negTrisM.length > 0) {
          const negTrisMm = new Float64Array(negTrisM.length);
          for (let i = 0; i < negTrisM.length; i++) {
            negTrisMm[i] = Math.round(negTrisM[i] * 1000 * 1e4) / 1e4;
          }
          negativeShellsMm.push(negTrisMm);
        }
      }
    }

    for (const child of n.children || []) {
      traverse(child, bodyMatrix);
    }
  };

  traverse(node);

  if (allTrisMetres.length === 0) {
    return {
      success: false,
      error: 'Mold contains no solid geometry.',
      warnings: ['No solid triangles extracted from mold node.'],
      mesh: { positions: new Float32Array(0), faces: new Uint32Array(0) },
      castVolumeMm3: 0,
      sizeMm: { width: 0, depth: 0, height: 0 },
      cavityComponents: 0,
    };
  }

  const closed = await castLaidOpenClamshell(node, geomShellsMm, geomNames, options);
  if (closed) return closed;

  const allTrisMm = new Float64Array(allTrisMetres.length);
  for (let i = 0; i < allTrisMetres.length; i++) {
    allTrisMm[i] = allTrisMetres[i] * 1000;
  }

  const res = await simulateCastFromMoldTriangles(allTrisMm, {
    ...options,
    halves: geomShellsMm.length > 0 ? geomShellsMm : undefined,
    negativeHalves: negativeShellsMm.length > 0 ? negativeShellsMm : undefined,
    rawTextures: rawTextures.length > 0 ? rawTextures : undefined,
    moldName: node.name,
  });
  if (warnings.length > 0) {
    res.warnings.push(...warnings);
  }
  return res;
}

/**
 * Entry point 2:
 * Simulates casting from a generated mold export result (MoldExportResult).
 * Assembles mold halves in closed pouring position and extracts the casting.
 */
export async function simulateCastFromMoldResult(
  mold: MoldExportResult,
  options?: MoldCastSimulationOptions,
): Promise<MoldCastSimulationResult> {
  if (!mold.success || !mold.bottomHalf || mold.bottomHalf.triangles.length === 0) {
    return {
      success: false,
      error: mold.error || 'Invalid or empty mold result.',
      warnings: mold.warnings ? [...mold.warnings] : [],
      mesh: { positions: new Float32Array(0), faces: new Uint32Array(0) },
      castVolumeMm3: 0,
      sizeMm: { width: 0, depth: 0, height: 0 },
      cavityComponents: 0,
    };
  }

  const botCenterX = (mold.bottomHalf.bounds.minX + mold.bottomHalf.bounds.maxX) / 2;
  const botPartingZ = mold.bottomHalf.partingZMm || mold.bottomHalf.bounds.maxZ;

  // Shift bottom half triangles by -botCenterX
  const botTrisMm = new Float64Array(mold.bottomHalf.triangles.length * 9);
  let bi = 0;
  for (const t of mold.bottomHalf.triangles) {
    botTrisMm[bi++] = t.a[0] - botCenterX;
    botTrisMm[bi++] = t.a[1];
    botTrisMm[bi++] = t.a[2];
    botTrisMm[bi++] = t.b[0] - botCenterX;
    botTrisMm[bi++] = t.b[1];
    botTrisMm[bi++] = t.b[2];
    botTrisMm[bi++] = t.c[0] - botCenterX;
    botTrisMm[bi++] = t.c[1];
    botTrisMm[bi++] = t.c[2];
  }

  if (mold.topHalf && mold.topHalf.triangles.length > 0) {
    // Clamshell mold: assemble top half (lid) mated directly onto bottom half
    const topCenterX = (mold.topHalf.bounds.minX + mold.topHalf.bounds.maxX) / 2;
    const lidPartingZ = mold.topHalf.partingZMm || findPartingZ(mold.topHalf.triangles) || mold.topHalf.bounds.maxZ;

    const topTrisMm = new Float64Array(mold.topHalf.triangles.length * 9);
    let ti = 0;
    for (const t of mold.topHalf.triangles) {
      for (const v of [t.a, t.b, t.c]) {
        topTrisMm[ti++] = v[0] - topCenterX;
        topTrisMm[ti++] = v[1];
        topTrisMm[ti++] = v[2];
      }
    }
    return restorePartFrame(await castClosedClamshell(botTrisMm, topTrisMm, botPartingZ, lidPartingZ, options, feedRouteOf(mold.features), ventStubsOf(mold.features)), mold, options);
  } else {
    // 1-part open mold
    return restorePartFrame(
      await simulateCastFromMoldTriangles(botTrisMm, {
        ...options,
        isClamshell: false,
        flipUpright: options?.orientUpright ?? true,
        halves: [botTrisMm],
      }),
      mold,
      options,
    );
  }
}

/**
 * Pours the closed mold's cavity with the air in it and takes out of the
 * casting what the air keeps: each trapped pocket as voxels, turned into a
 * solid by a level set and subtracted, so the walls stay the mold's own.
 */
function pourWithAir(
  wasm: ManifoldToplevel,
  cavity: ManifoldT,
  material: CastMaterialId,
): { casting: ManifoldT; report: CastFillReport; warning?: string } | null {
  const raw = manifoldToMeshMm(cavity);
  const flat = new Float64Array(raw.faces.length * 3);
  for (let i = 0; i < raw.faces.length; i++) {
    const v = raw.faces[i] * 3;
    flat[i * 3] = raw.positionsMm[v];
    flat[i * 3 + 1] = raw.positionsMm[v + 1];
    flat[i * 3 + 2] = raw.positionsMm[v + 2];
  }
  const b = cavity.boundingBox();
  const size: [number, number, number] = [b.max[0] - b.min[0], b.max[1] - b.min[1], b.max[2] - b.min[2]];
  if (!(size[0] > 0 && size[1] > 0 && size[2] > 0)) return null;
  const dom = voxelizeCavity(flat, fillCellMm(size));
  const res = simulateFill(dom, castMaterial(material).bubbleRiseMm);
  const report: CastFillReport = {
    filledShare: Math.round(res.filledShare * 1000) / 1000,
    trappedMm3: Math.round(res.trappedMm3),
    pockets: res.pockets.length,
    largestPocketMm3: Math.round(res.pockets[0]?.volumeMm3 ?? 0),
  };
  const volume = cavity.volume();
  // A cell's worth here and there is the voxels, not air.
  if (res.trappedMm3 < Math.max(2, volume * 0.003)) return { casting: cavity, report };
  const air = airSolid(wasm, dom, res);
  if (!air) return { casting: cavity, report };
  const casting = cavity.subtract(air);
  air.delete();
  const share = 1 - casting.volume() / volume;
  // A bubble a few millimetres across here and there is reported, not warned about.
  const matters = share >= 0.01 || report.largestPocketMm3 >= 30;
  const warning = matters
    ? `Air stays in ${res.pockets.length === 1 ? 'one pocket' : `${res.pockets.length} pockets`} (${report.trappedMm3} mm³, ${Math.round(share * 1000) / 10}% of the casting, ` +
      `the largest ${report.largestPocketMm3} mm³): the ${castMaterial(material).label.toLowerCase()} cannot get in where its air cannot get out. ` +
      'Each needs a vent from its top, or the mold filled from the bottom.'
    : undefined;
  return { casting, report, warning };
}

/** The trapped air as a solid: its cells and the mold cells round them, so the cut follows the mold's walls. */
function airSolid(wasm: ManifoldToplevel, d: FillDomain, res: FillResult): ManifoldT | null {
  const { cols, rows, layers, cell, inside } = d;
  const plane = cols * rows;
  const n = plane * layers;
  const air = new Uint8Array(n);
  let lo = [Infinity, Infinity, Infinity], hi = [-Infinity, -Infinity, -Infinity];
  for (let i = 0; i < n; i++) {
    if (!inside[i] || res.wet[i]) continue;
    const k = Math.floor(i / plane), rem = i - k * plane, r = Math.floor(rem / cols), c = rem - r * cols;
    for (let dk = -1; dk <= 1; dk++) for (let dr = -1; dr <= 1; dr++) for (let dc = -1; dc <= 1; dc++) {
      const kk = k + dk, rr = r + dr, cc = c + dc;
      if (kk < 0 || rr < 0 || cc < 0 || kk >= layers || rr >= rows || cc >= cols) continue;
      const j = (kk * rows + rr) * cols + cc;
      // Into the mold, never into liquid.
      if (j === i || !inside[j]) air[j] = 1;
    }
    lo = [Math.min(lo[0], c), Math.min(lo[1], r), Math.min(lo[2], k)];
    hi = [Math.max(hi[0], c), Math.max(hi[1], r), Math.max(hi[2], k)];
  }
  if (lo[0] === Infinity) return null;
  const at = (c: number, r: number, k: number) =>
    c < 0 || r < 0 || k < 0 || c >= cols || r >= rows || k >= layers ? 0 : air[(k * rows + r) * cols + c];
  // Trilinear between cell centres, 0.5 on the boundary.
  const sdf = (p: [number, number, number]) => {
    const fx = (p[0] - d.x0) / cell, fy = (p[1] - d.y0) / cell, fz = (p[2] - d.z0) / cell;
    const c = Math.floor(fx), r = Math.floor(fy), k = Math.floor(fz);
    const tx = fx - c, ty = fy - r, tz = fz - k;
    let v = 0;
    for (let a = 0; a < 2; a++) for (let b2 = 0; b2 < 2; b2++) for (let e = 0; e < 2; e++) {
      const w = (a ? tx : 1 - tx) * (b2 ? ty : 1 - ty) * (e ? tz : 1 - tz);
      if (w > 0) v += w * at(c + a, r + b2, k + e);
    }
    return v - 0.5;
  };
  const bounds = {
    min: [d.x0 + (lo[0] - 2) * cell, d.y0 + (lo[1] - 2) * cell, d.z0 + (lo[2] - 2) * cell] as [number, number, number],
    max: [d.x0 + (hi[0] + 2) * cell, d.y0 + (hi[1] + 2) * cell, d.z0 + (hi[2] + 2) * cell] as [number, number, number],
  };
  const m = wasm.Manifold.levelSet(sdf as (p: [number, number, number]) => number, bounds, cell);
  if (m.isEmpty()) {
    m.delete();
    return null;
  }
  return m;
}

/**
 * A clamshell's halves closed and poured: `bot` and `top` as they print, each
 * centred on x = 0, the lid turned over about X onto the cavity half, parting
 * face to parting face: (x, -y, botPartingZ + lidPartingZ - z).
 */
async function castClosedClamshell(
  bot: Float64Array,
  top: Float64Array,
  botPartingZ: number,
  lidPartingZ: number,
  options?: MoldCastSimulationOptions,
  feed?: FeedRoute,
  ventStubs?: VentStub[],
): Promise<MoldCastSimulationResult> {
  const seamZ = Math.fround(botPartingZ);
  for (let i = 2; i < bot.length; i += 3) {
    if (Math.abs(bot[i] - botPartingZ) < 1e-4) bot[i] = seamZ;
  }
  const turned = new Float64Array(top.length);
  for (let i = 0; i < top.length; i += 3) {
    turned[i] = top[i];
    turned[i + 1] = -top[i + 1];
    const zTop = top[i + 2];
    turned[i + 2] = Math.abs(zTop - lidPartingZ) < 1e-4 ? seamZ : botPartingZ + lidPartingZ - zTop;
  }
  const assembled = new Float64Array(bot.length + turned.length);
  assembled.set(bot, 0);
  assembled.set(turned, bot.length);
  // The route a little fatter than it was cut, so no skin of it is left on the
  // casting; the down-sprue and funnel much fatter, since a depth-field lid
  // draws them a grid cell ragged, and the down-sprue is a wall clear of the part.
  const z = (v: number) => botPartingZ + v;
  const ragged = FEED_WALL_MM - 0.1;
  const face = botPartingZ + lidPartingZ;
  const feedTrim: BoreCut[] = [
    ...(ventStubs ?? []).map((v): BoreCut => ({ a: [v.at[0], v.at[1], face + 1], b: [v.at[0], v.at[1], z(v.z)], r: v.r + VENT_TAPER_MM + 0.1, rB: v.r + 0.1 })),
    ...(feed ? feedTrimOf(feed, face, z, ragged) : []),
  ];
  return simulateCastFromMoldTriangles(assembled, { ...options, isClamshell: true, partingZ: botPartingZ, halves: [bot, turned], feedTrim });
}

/** A bottom fill's route as bores, in the closed mold's frame. */
function feedTrimOf(feed: FeedRoute, face: number, z: (v: number) => number, ragged: number): BoreCut[] {
  return [
    // The funnel, 45° from a millimetre above the lid's face...
    ...(feed.funnelR && feed.funnelDepth
      ? [{ a: [feed.down[0], feed.down[1], face + 1], b: [feed.down[0], feed.down[1], face - feed.funnelDepth - ragged], r: feed.funnelR + 1 + ragged, rB: feed.r + ragged } as BoreCut]
      : []),
    { a: [feed.down[0], feed.down[1], face + 1], b: [feed.down[0], feed.down[1], z(feed.runnerZ)], r: feed.r + ragged },
    { a: [feed.down[0], feed.down[1], z(feed.runnerZ)], b: [feed.gate[0], feed.gate[1], z(feed.runnerZ)], r: feed.r + 0.05, ends: true },
    { a: [feed.gate[0], feed.gate[1], z(feed.runnerZ)], b: [feed.gate[0], feed.gate[1], z(feed.gate[2])], r: feed.gateR + 0.05 },
  ];
}

/**
 * A generated clamshell in the scene lies as it prints, halves side by side,
 * and a pour into it filled each half on its own: a lined gear sculpture's
 * cast came back at 56% of the master, its gears half as thick, because the
 * lid's share of them was never in the mold. So a body that knows it lies
 * open (simulation.mold.laidOpen) is closed first, the lid being every geom
 * named "lid half", and poured through its sprue the way the Mold dialog's
 * cast is. Null when the body is not one of those.
 */
async function castLaidOpenClamshell(
  node: SceneNode,
  shells: Float64Array[],
  names: string[],
  options?: MoldCastSimulationOptions,
): Promise<MoldCastSimulationResult | null> {
  const rec = node.simulation?.mold;
  if (!rec?.laidOpen) return null;
  const isLid = names.map((n) => /lid[ _]half/i.test(n));
  if (!isLid.some(Boolean) || isLid.every(Boolean)) return null;

  const join = (lid: boolean) => {
    const parts = shells.filter((_, i) => isLid[i] === lid);
    const out = new Float64Array(parts.reduce((s, p) => s + p.length, 0));
    let o = 0;
    for (const p of parts) {
      out.set(p, o);
      o += p.length;
    }
    return out;
  };
  const bot = join(false);
  const top = join(true);
  // Back into the body's own frame, wherever it has been moved to: there the
  // plate's centreline is y = 0, the footprint of a half and its mirror.
  const toBody = getNodeWorldTransform(node).invert();
  const v = new THREE.Vector3();
  for (const a of [bot, top]) {
    for (let i = 0; i < a.length; i += 3) {
      v.set(a[i] / 1000, a[i + 1] / 1000, a[i + 2] / 1000).applyMatrix4(toBody);
      a[i] = v.x * 1000;
      a[i + 1] = v.y * 1000;
      a[i + 2] = v.z * 1000;
    }
  }
  // The plate's bed is the lowest point of either half; centre each half on x = 0.
  let bed = Infinity;
  for (const a of [bot, top]) for (let i = 2; i < a.length; i += 3) bed = Math.min(bed, a[i]);
  const settle = (a: Float64Array) => {
    let mn = Infinity, mx = -Infinity, zTop = -Infinity;
    for (let i = 0; i < a.length; i += 3) {
      mn = Math.min(mn, a[i]);
      mx = Math.max(mx, a[i]);
      zTop = Math.max(zTop, a[i + 2] - bed);
    }
    const cx = (mn + mx) / 2;
    for (let i = 0; i < a.length; i += 3) {
      a[i] -= cx;
      a[i + 2] -= bed;
    }
    return zTop;
  };
  const botTop = settle(bot);
  settle(top);
  // The cavity half has nothing above its parting face; the lid has its pins.
  const botPartingZ = rec.partingZMm?.cavity ?? botTop;
  const lidPartingZ = rec.partingZMm?.lid ?? findPartingZFromPositions(top);
  if (!(lidPartingZ > 0)) return null;

  // A closed mold is poured through its sprue: the side and level of an open pour do not apply.
  const rest: MoldCastSimulationOptions = { ...options };
  delete rest.pour;
  const res = await castClosedClamshell(bot, top, botPartingZ, lidPartingZ, rest, rec.feed, rec.ventStubs);
  return restorePartFrame(
    res,
    { moldType: 'clamshell', pullDirection: rec.pullDirection ?? '+z', cavityHoldsTop: Boolean(rec.cavityHoldsTop), topHalf: {} as MoldSummary['topHalf'] },
    rest,
  );
}

/**
 * Stands the casting the way the part stood in the scene.
 *
 * The casting comes out of the mold in the mold's frame: turned so the mold
 * opens along +Z, then half-turned about X if the cavity half holds the top of
 * the part, and half-turned again if an open mold's casting was flipped onto its
 * poured base. Undoing those puts it back beside the part it copies, the same
 * way up, which is what makes the two easy to compare.
 */
function restorePartFrame(
  res: MoldCastSimulationResult,
  mold: Pick<MoldSummary, 'moldType' | 'pullDirection' | 'cavityHoldsTop' | 'topHalf'>,
  options?: MoldCastSimulationOptions,
): MoldCastSimulationResult {
  if (!res.success || options?.orientUpright === false || !mold.pullDirection) return res;
  const open = !mold.topHalf;
  const halfTurned = Boolean(mold.cavityHoldsTop) !== open;
  if (!halfTurned && mold.pullDirection === '+z') return res;

  const pos = new Float32Array(res.mesh.positions);
  let mnX = Infinity, mxX = -Infinity, mnY = Infinity, mxY = -Infinity, mnZ = Infinity, mxZ = -Infinity;
  for (let i = 0; i < pos.length; i += 3) {
    let x = pos[i], y = pos[i + 1], z = pos[i + 2];
    if (halfTurned) {
      y = -y;
      z = -z;
    }
    [x, y, z] = unrotateFromPull(mold.pullDirection, x, y, z);
    pos[i] = x;
    pos[i + 1] = y;
    pos[i + 2] = z;
    if (x < mnX) mnX = x;
    if (x > mxX) mxX = x;
    if (y < mnY) mnY = y;
    if (y > mxY) mxY = y;
    if (z < mnZ) mnZ = z;
    if (z > mxZ) mxZ = z;
  }
  const cx = (mnX + mxX) / 2, cy = (mnY + mxY) / 2;
  for (let i = 0; i < pos.length; i += 3) {
    pos[i] -= cx;
    pos[i + 1] -= cy;
    pos[i + 2] -= mnZ;
  }
  return {
    ...res,
    mesh: { positions: pos, faces: res.mesh.faces },
    sizeMm: {
      width: Math.round((mxX - mnX) * 100) / 100,
      depth: Math.round((mxY - mnY) * 100) / 100,
      height: Math.round((mxZ - mnZ) * 100) / 100,
    },
  };
}

function findPartingZFromPositions(positions: ArrayLike<number>): number {
  const zCounts = new Map<number, number>();
  for (let i = 0; i + 8 < positions.length; i += 9) {
    const az = positions[i + 2], bz = positions[i + 5], cz = positions[i + 8];
    if (Math.abs(az - bz) < 1e-2 && Math.abs(bz - cz) < 1e-2 && az > 1) {
      const k = Math.round(az * 10) / 10;
      zCounts.set(k, (zCounts.get(k) ?? 0) + 1);
    }
  }
  let bestZ = 0;
  let maxCount = 0;
  for (const [z, count] of zCounts.entries()) {
    if (count > maxCount) {
      maxCount = count;
      bestZ = z;
    }
  }
  return bestZ;
}

/**
 * Simulates casting from worker preview buffers (MoldSummary + bottom/top Float32Array positions).
 */
export async function simulateCastFromMoldBuffers(
  summary: MoldSummary,
  bottomPositions: Float32Array,
  topPositions?: Float32Array | null,
  options?: MoldCastSimulationOptions,
): Promise<MoldCastSimulationResult> {
  if (!summary.success || bottomPositions.length < 9) {
    return {
      success: false,
      error: summary.error || 'Invalid or empty mold preview buffers.',
      warnings: summary.warnings ? [...summary.warnings] : [],
      mesh: { positions: new Float32Array(0), faces: new Uint32Array(0) },
      castVolumeMm3: 0,
      sizeMm: { width: 0, depth: 0, height: 0 },
      cavityComponents: 0,
    };
  }

  const botCenterX = (summary.bottomHalf.bounds.minX + summary.bottomHalf.bounds.maxX) / 2;
  const botPartingZ = summary.bottomHalf.partingZMm || summary.bottomHalf.bounds.maxZ;

  const botTrisMm = new Float64Array(bottomPositions.length);
  for (let i = 0; i < bottomPositions.length; i += 3) {
    botTrisMm[i] = bottomPositions[i] - botCenterX;
    botTrisMm[i + 1] = bottomPositions[i + 1];
    botTrisMm[i + 2] = bottomPositions[i + 2];
  }

  if (summary.topHalf && topPositions && topPositions.length >= 9) {
    const topCenterX = (summary.topHalf.bounds.minX + summary.topHalf.bounds.maxX) / 2;
    const lidPartingZ = summary.topHalf.partingZMm || findPartingZFromPositions(topPositions) || summary.topHalf.bounds.maxZ;

    const topTrisMm = new Float64Array(topPositions.length);
    for (let i = 0; i < topPositions.length; i += 3) {
      topTrisMm[i] = topPositions[i] - topCenterX;
      topTrisMm[i + 1] = topPositions[i + 1];
      topTrisMm[i + 2] = topPositions[i + 2];
    }
    return restorePartFrame(
      await castClosedClamshell(botTrisMm, topTrisMm, botPartingZ, lidPartingZ, options, feedRouteOf(summary.features), ventStubsOf(summary.features)),
      summary,
      options,
    );
  }

  return restorePartFrame(
    await simulateCastFromMoldTriangles(botTrisMm, {
      ...options,
      isClamshell: false,
      flipUpright: options?.orientUpright ?? true,
      halves: [botTrisMm],
    }),
    summary,
    options,
  );
}

/**
 * Entry point 3:
 * Simulates casting from raw mold triangles (in millimetres).
 */
export async function simulateCastFromMoldTriangles(
  trisMm: Float64Array | number[],
  options?: InternalCastOptions,
): Promise<MoldCastSimulationResult> {
  const warnings: string[] = [];

  if (!trisMm || trisMm.length < 9) {
    return {
      success: false,
      error: 'No triangles provided for mold casting simulation.',
      warnings: ['Input triangles array is empty or too short.'],
      mesh: { positions: new Float32Array(0), faces: new Uint32Array(0) },
      castVolumeMm3: 0,
      sizeMm: { width: 0, depth: 0, height: 0 },
      cavityComponents: 0,
    };
  }

  // 1. Compute mold bounding box
  let minX = Infinity, maxX = -Infinity;
  let minY = Infinity, maxY = -Infinity;
  let minZ = Infinity, maxZ = -Infinity;
  for (let i = 0; i < trisMm.length; i += 3) {
    const x = trisMm[i], y = trisMm[i + 1], z = trisMm[i + 2];
    if (x < minX) minX = x;
    if (x > maxX) maxX = x;
    if (y < minY) minY = y;
    if (y > maxY) maxY = y;
    if (z < minZ) minZ = z;
    if (z > maxZ) maxZ = z;
  }

  const width = maxX - minX;
  const depth = maxY - minY;
  const height = maxZ - minZ;

  if (width <= 0 || depth <= 0 || height <= 0) {
    return {
      success: false,
      error: 'Mold geometry has degenerate zero bounding extents.',
      warnings: [],
      mesh: { positions: new Float32Array(0), faces: new Uint32Array(0) },
      castVolumeMm3: 0,
      sizeMm: { width: 0, depth: 0, height: 0 },
      cavityComponents: 0,
    };
  }

  // 2. Interior cavity probe box bounds
  const insetXY = Math.min(0.5, Math.max(0.01, width * 0.01), Math.max(0.01, depth * 0.01));
  const boxMinX = minX + insetXY;
  const boxMaxX = maxX - insetXY;
  const boxMinY = minY + insetXY;
  const boxMaxY = maxY - insetXY;
  const boxMinZ = minZ + 0.001;
  const boxMaxZ = maxZ - 0.001;

  const boxW = boxMaxX - boxMinX;
  const boxD = boxMaxY - boxMinY;
  const boxH = boxMaxZ - boxMinZ;

  if (boxW <= 0 || boxD <= 0 || boxH <= 0) {
    return {
      success: false,
      error: 'Mold is too thin to place an interior probe volume.',
      warnings: [],
      mesh: { positions: new Float32Array(0), faces: new Uint32Array(0) },
      castVolumeMm3: 0,
      sizeMm: { width: 0, depth: 0, height: 0 },
      cavityComponents: 0,
    };
  }

  // 3. Primary Path: Manifold 3D CSG
  try {
    const wasm = await loadManifold();
    const probeBox = wasm.Manifold.cube([boxW, boxD, boxH], false).translate([boxMinX, boxMinY, boxMinZ]);

    // Convert mold shells to Manifold: exact vertex welding first, so fine
    // boolean meshes never have sub-millimetre intersection edges collapsed,
    // then 0.01 mm seam welding. Neither fills a hole.
    const closedSolid = (positions: Float32Array, faces: Uint32Array): ManifoldT | null => {
      if (faces.length < 12) return null;
      try {
        const m = new wasm.Manifold(new wasm.Mesh({ numProp: 3, vertProperties: positions, triVerts: faces }));
        if (m.status() === 'NoError' && !m.isEmpty()) return m;
        m.delete();
      } catch {
        // Not a closed solid.
      }
      return null;
    };
    // Why the last shell that would not close did not, for the refusal.
    let unsolidShell: string | undefined;
    const convertSoupToManifold = (soup: ArrayLike<number>): ManifoldT | null => {
      const exact = weldTriangles(soup, 0);
      const direct = closedSolid(exact.positions, exact.faces);
      if (direct) return direct;
      // Heals float32 STL seam cracks.
      const { positions, faces } = weldTriangles(soup, 0.01);
      const welded = closedSolid(positions, faces);
      if (welded) return welded;
      if (faces.length < 12) return null;

      // A shell that closes only by cutting out what will not weld and capping
      // the holes flat is a different mold: a cap across a core let the pour
      // into it and the casting came back with a floor. So it is refused, with
      // what is wrong, rather than cast.
      const integrity = analyzeMesh(positions, faces);
      const open = (integrity?.boundaryEdges ?? 0) + (integrity?.nonManifoldEdges ?? 0);
      unsolidShell ??= open > 0
        ? `${open.toLocaleString()} of its edges are open or shared by more than two faces`
        : integrity && !integrity.consistentlyWound
        ? 'its faces are not all wound the same way'
        : 'its surface cannot be read as a solid';
      return null;
    };

    const shells: ManifoldT[] = [];

    if (options?.halves && options.halves.length > 0) {
      for (const h of options.halves) {
        const m = convertSoupToManifold(h);
        if (m) shells.push(m);
      }
    }

    if (shells.length === 0) {
      // None closed apart; the whole may, or its two sides cut at the parting plane.
      unsolidShell = undefined;
      const m = convertSoupToManifold(trisMm);
      if (m) {
        shells.push(m);
      } else if (options?.isClamshell && options?.partingZ !== undefined) {
        // Try splitting by parting plane
        unsolidShell = undefined;
        const pZ = options.partingZ;
        const bot: number[] = [];
        const top: number[] = [];
        for (let i = 0; i + 8 < trisMm.length; i += 9) {
          const zAvg = (trisMm[i + 2] + trisMm[i + 5] + trisMm[i + 8]) / 3;
          const target = zAvg <= pZ ? bot : top;
          for (let k = 0; k < 9; k++) target.push(trisMm[i + k]);
        }
        for (const piece of [bot, top]) {
          if (piece.length < 36) continue;
          const pm = convertSoupToManifold(piece);
          if (pm) shells.push(pm);
        }
      }
    }

    if (unsolidShell) {
      for (const shell of shells) shell.delete();
      probeBox.delete();
      return {
        success: false,
        error: `${options?.moldName ?? 'The mold'} is not a closed solid: ${unsolidShell}, so what it would cast cannot be worked out. ` +
          'Repair it (Repair Mesh) and check the result, or make the mold again.',
        warnings,
        mesh: { positions: new Float32Array(0), faces: new Uint32Array(0) },
        castVolumeMm3: 0,
        sizeMm: { width: 0, depth: 0, height: 0 },
        cavityComponents: 0,
      };
    }

    if (shells.length > 0) {
      let cavity: ManifoldT;
      if (options?.isClamshell) {
        // Clamshell: subtract each half sequentially to avoid coplanar parting face union issues
        let cur = probeBox;
        for (const shell of shells) {
          const next = cur.subtract(shell);
          cur.delete();
          shell.delete();
          cur = next;
        }
        cavity = cur;
      } else {
        // Single mold body: union positive geoms into a single solid, subtract any uncompiled negative CSG geoms, then subtract from probeBox
        let moldSolid = shells[0];
        for (let i = 1; i < shells.length; i++) {
          const unioned = moldSolid.add(shells[i]);
          moldSolid.delete();
          shells[i].delete();
          moldSolid = unioned;
        }
        if (options?.negativeHalves && options.negativeHalves.length > 0) {
          for (const negSoup of options.negativeHalves) {
            const negM = convertSoupToManifold(negSoup);
            if (negM) {
              const diffed = moldSolid.subtract(negM);
              moldSolid.delete();
              negM.delete();
              moldSolid = diffed;
            }
          }
        }
        cavity = probeBox.subtract(moldSolid);
        probeBox.delete();
        moldSolid.delete();
      }

      const probe = { minX: boxMinX, maxX: boxMaxX, minY: boxMinY, maxY: boxMaxY, minZ: boxMinZ, maxZ: boxMaxZ };
      if (options?.pour) {
        const poured = cavity.isEmpty() ? null : pourIntoCavity(wasm, cavity, probe, options.pour);
        cavity.delete();
        if (!poured) {
          const sides = !options.pour.direction || options.pour.direction === 'auto';
          return {
            success: false,
            error: sides
              ? 'Nothing here holds a pour: there is no pocket open on one side only.'
              : `Nothing here holds a pour from ${options.pour.direction}.`,
            warnings,
            mesh: { positions: new Float32Array(0), faces: new Uint32Array(0) },
            castVolumeMm3: 0,
            sizeMm: { width: 0, depth: 0, height: 0 },
            cavityComponents: 0,
          };
        }
        // The casting comes turned with the side poured from up, where a sprue stands.
        const casting = options.trimChannels ? trimRunnerChannels(wasm, poured.casting) : poured.casting;
        const raw = manifoldToMeshMm(casting);
        casting.delete();
        // Turned out of the mold onto the face the pour left, unless kept as poured.
        const res = finalizeCastMesh(raw.positionsMm, raw.faces, poured.pieces, { ...options, flipUpright: options.orientUpright !== false }, warnings);
        return { ...res, pour: poured.info };
      }

      if (!cavity.isEmpty()) {
        const parts = cavity.decompose();
        cavity.delete();
        const cavityComponents = parts.length;

        if (parts.length > 0) {
          // Keep the largest piece that pours: one open on at most one face of
          // the probe box. Air reaching round the outside of the mold touches
          // several faces, and round a sleeve it can outweigh the cavity.
          let best = parts[0];
          let bestKey = -Infinity;
          for (const p of parts) {
            const key = p.volume() + (probeFacesTouched(p, probe) <= 1 ? 1e15 : 0);
            if (key > bestKey) {
              bestKey = key;
              best = p;
            }
          }
          for (const p of parts) {
            if (p !== best) p.delete();
          }
          let fill: CastFillReport | undefined;
          if (options?.isClamshell && options.airAware !== false) {
            const poured = pourWithAir(wasm, best, options.castMaterial ?? 'epoxy');
            if (poured) {
              fill = poured.report;
              if (poured.casting !== best) {
                best.delete();
                best = poured.casting;
              }
              if (poured.warning) warnings.push(poured.warning);
            }
          }
          // Trimmed, the bottom fill's down-sprue, runner and gate come off along
          // their own bores, and then the sprue and vents off the top.
          if (options?.trimChannels && options.feedTrim?.length) best = cutBores(wasm, best, options.feedTrim);
          if (options?.trimChannels) best = trimRunnerChannels(wasm, best);
          // Trimming along a depth-field lid's ragged holes leaves slivers of
          // nothing floating where they were; they are not casting.
          if (options?.trimChannels) best = dropSlivers(wasm, best);

          const raw = manifoldToMeshMm(best);
          best.delete();

          const res = finalizeCastMesh(raw.positionsMm, raw.faces, cavityComponents, options, warnings);
          return fill ? { ...res, fill } : res;
        }
      } else {
        cavity.delete();
      }
    } else {
      probeBox.delete();
    }
  } catch (err) {
    warnings.push(`Manifold CSG error: ${err instanceof Error ? err.message : String(err)}`);
  }

  // A pour picks its side and level from the exact cavity; the column fallback
  // can do neither, so it would hand back something other than what was asked.
  if (options?.pour) {
    return {
      success: false,
      error: warnings.find((w) => w.startsWith('Manifold CSG error')) ?? 'The mold is not a closed solid, so nothing can be poured into it.',
      warnings,
      mesh: { positions: new Float32Array(0), faces: new Uint32Array(0) },
      castVolumeMm3: 0,
      sizeMm: { width: 0, depth: 0, height: 0 },
      cavityComponents: 0,
    };
  }

  // 4. Fallback Path: Exact Column Spans + meshField
  warnings.push('Falling back to column spans and surface nets for mold cavity simulation.');
  return fallbackColumnSpansCast(trisMm, boxMinX, boxMaxX, boxMinY, boxMaxY, minZ, maxZ, options, warnings);
}

/** The casting less any piece under a cubic millimetre, or a thousandth of it. Consumes `casting`. */
function dropSlivers(wasm: ManifoldToplevel, casting: ManifoldT): ManifoldT {
  const parts = casting.decompose();
  if (parts.length <= 1) {
    for (const p of parts) p.delete();
    return casting;
  }
  const floor = Math.max(1, casting.volume() * 1e-3);
  const kept = parts.filter((p) => p.volume() >= floor);
  for (const p of parts) if (!kept.includes(p)) p.delete();
  if (kept.length === 0) return casting;
  casting.delete();
  const out = wasm.Manifold.compose(kept);
  for (const p of kept) p.delete();
  return out;
}

/**
 * Cuts the narrow sprue and vent channels off the top of a casting: slices
 * down from the top until one is wider than a sprue and vent together, and
 * takes everything above it. Consumes `casting`.
 */
function trimRunnerChannels(wasm: ManifoldToplevel, casting: ManifoldT): ManifoldT {
  const { min, max } = casting.boundingBox();
  const zTop = max[2];
  const spanH = zTop - min[2];
  if (spanH <= 2) return casting;
  const w = max[0] - min[0];
  const d = max[1] - min[1];
  // Check slices from top down to find where narrow channel widens to part body
  let cutZ = zTop;
  for (let z = zTop - 0.5; z >= zTop - spanH * 0.4; z -= 0.5) {
    const sliceBox = wasm.Manifold.cube([w * 2, d * 2, 0.5], false).translate([min[0] - w / 2, min[1] - d / 2, z - 0.25]);
    const slice = casting.intersect(sliceBox);
    const sliceArea = slice.volume() / 0.5;
    sliceBox.delete();
    slice.delete();
    // A sprue + vent channel total area is <= 65 mm²
    if (sliceArea > 75) {
      cutZ = z + 0.5;
      break;
    }
  }
  if (!(cutZ < zTop - 0.5)) return casting;
  const cutter = wasm.Manifold.cube([w * 2, d * 2, zTop - cutZ + 1], false).translate([min[0] - w / 2, min[1] - d / 2, cutZ]);
  const trimmed = casting.subtract(cutter);
  cutter.delete();
  casting.delete();
  return trimmed;
}

/**
 * Normalizes mesh orientation:
 * - Flips 180° around X if inverted open-mold casting (or if flipUpright is requested)
 * - Centers in XY on (0, 0)
 * - Rests on Z = 0
 */
function finalizeCastMesh(
  positionsMm: Float32Array,
  faces: Uint32Array,
  cavityComponents: number,
  options?: InternalCastOptions,
  warnings: string[] = [],
): MoldCastSimulationResult {
  const pos = new Float32Array(positionsMm);

  let mnZ = Infinity, mxZ = -Infinity;
  for (let i = 2; i < pos.length; i += 3) {
    const z = pos[i];
    if (z < mnZ) mnZ = z;
    if (z > mxZ) mxZ = z;
  }
  const h = mxZ - mnZ;

  // In an open-top mold (cavity open at maxZ and closed by a solid floor at minZ),
  // the open pour mouth at maxZ is the flat base of the cast part (e.g. a statue's
  // pedestal base or a plaque's flat back). Flipping 180° around X places that flat
  // poured base on Z = 0 so the demolded part stands upright.
  let shouldFlip = false;
  if (options?.flipUpright !== undefined) {
    shouldFlip = options.flipUpright;
  } else if (options?.orientUpright === false) {
    shouldFlip = false;
  } else if (!options?.isClamshell && h > 1e-4) {
    shouldFlip = options?.orientUpright ?? true;
  }

  if (shouldFlip) {
    // Flip 180° around X: (x, -y, -z)
    for (let i = 0; i < pos.length; i += 3) {
      pos[i + 1] = -pos[i + 1];
      pos[i + 2] = -pos[i + 2];
    }
  }

  // Bounds & re-centering
  let mnX = Infinity, mxX = -Infinity;
  let mnY = Infinity, mxY = -Infinity;
  mnZ = Infinity; mxZ = -Infinity;
  for (let i = 0; i < pos.length; i += 3) {
    const x = pos[i], y = pos[i + 1], z = pos[i + 2];
    if (x < mnX) mnX = x;
    if (x > mxX) mxX = x;
    if (y < mnY) mnY = y;
    if (y > mxY) mxY = y;
    if (z < mnZ) mnZ = z;
    if (z > mxZ) mxZ = z;
  }

  const cx = (mnX + mxX) / 2;
  const cy = (mnY + mxY) / 2;
  const cz = mnZ;

  for (let i = 0; i < pos.length; i += 3) {
    pos[i] -= cx;
    pos[i + 1] -= cy;
    pos[i + 2] -= cz;
  }

  const castVolumeMm3 = computeMeshVolume(pos, faces);
  const sizeMm = {
    width: Math.round((mxX - mnX) * 100) / 100,
    depth: Math.round((mxY - mnY) * 100) / 100,
    height: Math.round((mxZ - mnZ) * 100) / 100,
  };

  let textures: SurfaceTexture[] | undefined;
  if (options?.rawTextures && options.rawTextures.length > 0) {
    textures = options.rawTextures.map((rt) => {
      const atMm: [number, number, number] = shouldFlip
        ? [rt.worldAtMm[0], -rt.worldAtMm[1], -rt.worldAtMm[2]]
        : [rt.worldAtMm[0], rt.worldAtMm[1], rt.worldAtMm[2]];
      const moldN = new THREE.Vector3(
        rt.worldNormal[0],
        shouldFlip ? -rt.worldNormal[1] : rt.worldNormal[1],
        shouldFlip ? -rt.worldNormal[2] : rt.worldNormal[2],
      ).normalize();
      // The cast face normal points opposite to the mold cavity surface normal
      const castN = moldN.clone().negate();
      const targetUp = new THREE.Vector3(
        rt.worldUp[0],
        shouldFlip ? -rt.worldUp[1] : rt.worldUp[1],
        shouldFlip ? -rt.worldUp[2] : rt.worldUp[2],
      ).normalize();

      // Compute default planar u, v on the cast face
      const u0 = new THREE.Vector3(1, 0, 0);
      if (Math.abs(castN.x) > 0.85) u0.set(0, 1, 0);
      u0.addScaledVector(castN, -u0.dot(castN)).normalize();
      const v0 = new THREE.Vector3().crossVectors(castN, u0).normalize();
      let twistDeg = rt.texture.twistDeg ?? 0;
      if (v0.dot(targetUp) < -0.5) {
        twistDeg = (twistDeg + 180) % 360;
      }

      const castAtM = [
        Math.round(((atMm[0] - cx) / 1000) * 1e6) / 1e6,
        Math.round(((atMm[1] - cy) / 1000) * 1e6) / 1e6,
        Math.round(((atMm[2] - cz) / 1000) * 1e6) / 1e6,
      ];
      return {
        ...rt.texture,
        depthM: -rt.texture.depthM,
        scale: -(rt.texture.scale ?? 1),
        seedAt: castAtM,
        seedNormal: [
          Math.round(castN.x * 1e6) / 1e6,
          Math.round(castN.y * 1e6) / 1e6,
          Math.round(castN.z * 1e6) / 1e6,
        ],
        ...(twistDeg ? { twistDeg } : { twistDeg: undefined }),
      };
    });
  }

  return {
    success: true,
    warnings,
    mesh: { positions: pos, faces: Uint32Array.from(faces) },
    castVolumeMm3: Math.round(castVolumeMm3 * 10) / 10,
    sizeMm,
    cavityComponents,
    ...(textures && textures.length > 0 ? { textures } : {}),
  };
}

/**
 * Fallback Path using castColumnSpans and meshField.
 */
function fallbackColumnSpansCast(
  trisMm: Float64Array | number[],
  boxMinX: number,
  boxMaxX: number,
  boxMinY: number,
  boxMaxY: number,
  minZ: number,
  maxZ: number,
  options?: InternalCastOptions,
  warnings: string[] = [],
): MoldCastSimulationResult {
  const trisFlat = trisMm instanceof Float64Array ? trisMm : new Float64Array(trisMm);
  const bw = boxMaxX - boxMinX;
  const bd = boxMaxY - boxMinY;
  const bh = maxZ - minZ;

  const targetCols = 60;
  const stepX = Math.max(0.5, bw / targetCols);
  const stepY = Math.max(0.5, bd / targetCols);
  const cols = Math.max(4, Math.round(bw / stepX) + 1);
  const rows = Math.max(4, Math.round(bd / stepY) + 1);

  const grid: ColumnGrid = {
    minX: boxMinX,
    minY: boxMinY,
    stepX,
    stepY,
    cols,
    rows,
  };

  const spans = castColumnSpans(trisFlat, grid);

  // Extract cavity intervals per column
  const cavityStarts: number[][] = Array.from({ length: cols * rows }, () => []);
  const cavityEnds: number[][] = Array.from({ length: cols * rows }, () => []);

  for (let k = 0; k < cols * rows; k++) {
    const o0 = spans.offset[k];
    const o1 = spans.offset[k + 1];
    if (o1 <= o0) continue;

    // Internal gaps between solid spans
    for (let i = o0; i + 3 < o1; i += 2) {
      const gapBot = spans.z[i + 1];
      const gapTop = spans.z[i + 2];
      if (gapTop - gapBot > 0.05) {
        cavityStarts[k].push(gapBot);
        cavityEnds[k].push(gapTop);
      }
    }

    // Open-top mold cavity mouth
    if (!options?.isClamshell) {
      const floorZ = spans.z[o0];
      const ceilZ = spans.z[o1 - 1];
      if (floorZ <= minZ + 5 && ceilZ < maxZ - 0.5) {
        cavityStarts[k].push(ceilZ);
        cavityEnds[k].push(maxZ);
      }
    }
  }

  // Dual contouring using meshField
  const field = (x: number, y: number, z: number) => {
    // World coordinates
    const wx = boxMinX + x;
    const wy = boxMinY + y;
    const wz = maxZ + z; // z in [-bh, 0] -> wz in [minZ, maxZ]

    const c = Math.max(0, Math.min(cols - 1, Math.round((wx - boxMinX) / stepX)));
    const r = Math.max(0, Math.min(rows - 1, Math.round((wy - boxMinY) / stepY)));
    const k = r * cols + c;

    const starts = cavityStarts[k];
    const ends = cavityEnds[k];

    let minDist = -Infinity;
    for (let i = 0; i < starts.length; i++) {
      const s = starts[i];
      const e = ends[i];
      if (wz >= s && wz <= e) {
        // Inside cavity
        const dist = Math.min(wz - s, e - wz);
        if (dist > minDist) minDist = dist;
      }
    }
    if (minDist >= 0) return minDist;

    // Outside cavity
    let closest = Infinity;
    for (let i = 0; i < starts.length; i++) {
      const s = starts[i];
      const e = ends[i];
      const d = wz < s ? s - wz : wz - e;
      if (d < closest) closest = d;
    }
    return -closest;
  };

  const stock = { widthMm: bw, depthMm: bd, thicknessMm: bh };
  const fm = meshField(field, stock, { minCellMm: Math.max(stepX, stepY) });

  if (fm.faces.length === 0) {
    return {
      success: false,
      error: 'Fallback mesher could not find closed cavity surface.',
      warnings,
      mesh: { positions: new Float32Array(0), faces: new Uint32Array(0) },
      castVolumeMm3: 0,
      sizeMm: { width: 0, depth: 0, height: 0 },
      cavityComponents: 0,
    };
  }

  // Map vertex positions back to world mm
  const pos = new Float32Array(fm.positions.length);
  for (let i = 0; i < fm.positions.length; i += 3) {
    pos[i] = fm.positions[i] + boxMinX;
    pos[i + 1] = fm.positions[i + 1] + boxMinY;
    pos[i + 2] = fm.positions[i + 2] + maxZ;
  }

  return finalizeCastMesh(pos, fm.faces, 1, options, warnings);
}
